import{_ as t}from"./chunks/db606f6d4881435066ca.BHWU8uMK.js";import{_ as r,C as o,o as l,c as i,j as e,a as n,E as s,a5 as h}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"我必须学习这些高收入技能（如果我想赚钱的话）","description":"","frontmatter":{"title":"我必须学习这些高收入技能（如果我想赚钱的话）","originalTitle":"I HAD To Learn These High-Income Skills (If I Wanted To Make Money)","date":"2023-08-05","originalUrl":"https://thedankoe.com/letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money/","minutes":11,"sourceHash":"6b8f97162e159228b0e2777a16c44b6f7f7729f916dcf2a1308eba71c1313afb","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money/"}]]},"headers":[],"relativePath":"letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money.md","filePath":"letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money.md"}'),c={name:"letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money.md"};function d(m,p,u,f,k,b){const a=o("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=e("h1",{id:"我必须学习这些高收入技能-如果我想赚钱的话",tabindex:"-1"},[n("我必须学习这些高收入技能（如果我想赚钱的话） "),e("a",{class:"header-anchor",href:"#我必须学习这些高收入技能-如果我想赚钱的话","aria-label":'Permalink to "我必须学习这些高收入技能（如果我想赚钱的话）"'},"​")],-1)),s(a),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/48LrD1SW20I?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我的商业之旅很简单。</p><p>我几乎尝试了所有事情，并且都失败了。</p><p>但是，正如我们在这里所知道的，失败是一种恩赐。</p><p>它是一个数据点，揭示了哪些地方可以改进。</p><p>不经历失败的人，就不会获得成功。</p><p>仔细想想这根本说不通……去期盼那种没有失败的成功，要知道，成功只有以失败为参照点时才存在。</p><p>如果你从出生的那一天起就“成功”了（在很多方面你确实如此），你会把它看作是成功吗？还是你会把它看作是正常的生活？</p><p>你必须将新目标设为高点，将巨大的失败接纳为低点，并在挣扎中起舞，从而将这种有意义的反差完美融合。</p><p>这引出了一个重要观点。</p><p>自力更生。</p><p>富二代们并非自力更生，因为他们没有教导自己去这样做。成功是他们的常态。以至于他们没有新的潜力可以去发掘。并非所有的富二代都抑郁且不善社交，但有很多人确实如此，因为他们没有理由去培养一套技能，以实现一个自发设定的目标。</p><p>没人能教你<strong>自力</strong>更生。</p><p>否则，那就不叫自力更生了。</p><p>要在任何领域（从金钱到人际关系再到健康）实现自力更生，你需要具备那些能够弥补现状与目标之间差距的技能。大多数人不知道自己想要什么，甚至更多的人根本不认为自己的现状是个问题。</p><p>注意上面那段话中的“需要”一词。</p><p>为了实现自力更生，有些技能是你<strong>需要</strong>学习的。</p><p>它们不是可选项。</p><p>我再重复一遍。它们<strong>绝不是</strong>可选项。</p><p>这封信接下来的内容并不是某种个人方法论。</p><p>我所展示的这些技能，是每一个成功人士要想在商业、人际关系以及（可以说）健康方面达到一定成功水平，都必须学习（或花钱雇人来做）的——尽管你可能还不认为它们属于健康技能。</p><p>我在7种商业模式上都失败了。</p><p>原因是，我并不了解那些真正能让我赚钱的技能。</p><p>不，它们绝不是人们告诉你要学的那些现代技能，比如网页设计、电子邮件营销或潜在客户生成（引流）。</p><p>我们需要层层剥开，触及让这些技能起作用的本质。</p><p>一旦你真正地、通过实践理解了它们，你就能让金钱像水槽里的水一样源源不断地流进来。</p><h2 id="常青技能" tabindex="-1">常青技能 <a class="header-anchor" href="#常青技能" aria-label="Permalink to &quot;常青技能&quot;">​</a></h2><p>我正处在打造一项软件业务的过程中，我迷茫了。</p><p>公司架构、商标律师、一般律师、招聘、设计阶段、运营协议等等。</p><p>但是，这些都是我可以边做边学的东西。</p><p>所有其他企业（非<a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">一人企业</a>）在某个阶段都需要学习创办一家“真正”企业的门道——所以网上有大量的可用资源。</p><p>有了一人企业，你可以建立一个社交媒体账号，创造一个数字产品，并免费推广它（在大多数初学者的情况下）。</p><p>关键在于，创业所需的技术技能都摆在那里，随时可以去学。</p><p>但我们在这儿不是来谈论这些的。</p><p>因为如果那些是商业成功的驱动力，大多数企业就不会失败了。</p><p><strong>营销和销售</strong>则不同。</p><p>它们是常青技能。</p><p>它们需要创造力、经验以及对你所在行业大局的理解才能奏效。</p><p>营销和销售是赚钱的人和不赚钱的人之间的决定性差异。</p><p>让我们以一家科技初创公司为例。</p><p>他们拥有令人惊叹的开发人员和一个绝佳的点子。</p><p>他们开发了软件，上线发布，然后……什么也没发生。</p><p>他们没有信任他们的受众。他们没有能抓住目标市场注意力的推广活动。他们没有解决一个具体的迫切问题。他们不打算随着时间的推移提高人们对问题的认知（他们没有通过内容去<strong>创造</strong>自己的客户）。他们没有准备好任何能让他们写出优秀内容、广告并将观众转化为客户的“火力”。</p><p><strong>营销和销售</strong>加上<strong>写作和表达</strong>，就是你创造价值的方式。</p><p>我以前讨论过，价值创造是建立我一人企业的单一技能。<a href="/letters/value-creation-the-skill-that-built-my-one-person-business">这封信</a>会把你做的任何事情变成一项有利可图的努力。</p><p>要总结必须在你写作和表达中展现的营销和销售原则，你需要：</p><ul><li>一个渴望的结果</li><li>一个阻挡在前面的迫切问题</li><li>一条达到该结果的行之有效的路径（你的经验所独有的）</li><li>你所针对的人群的认知水平（他们对自己的问题有多清楚？）</li><li>一个基于人类8大欲望来谈论该问题的切入点</li><li>一系列好处以及解决这个问题将如何影响他们的生活</li><li>证明你能解决那个问题的证据（来自你自己或以前的客户）</li><li>一个能在互联网信息的汪洋大海中抓住眼球的宏大理念</li><li>一个能推他们一把、促成决定的风险逆转或保证承诺</li></ul><p>营销和销售之所以常青，是因为它们基于机制、人类行为和心理学。它们始于心智，万物皆然。</p><p>在你的内容、落地页以及你与人或客户沟通的任何其他地方，这些都是强有力的核心谈资。</p><p>你并不<strong>仅仅</strong>是在营销某种产品或服务。</p><p>当你写内容时，你是在推销你的想法。</p><p>你的内容得不到互动或粉丝，原因就是你没法将上述列表中的要素结合起来，形成有影响力的写作和表达。</p><p>还记得我们是怎么讨论自力更生的吗？</p><p>剩下的就看你的了。</p><p>痴迷地研究营销和销售，但要把上述要点牢记在心，这样你就能过滤出什么是重要的。</p><h2 id="常青的载体" tabindex="-1">常青的载体 <a class="header-anchor" href="#常青的载体" aria-label="Permalink to &quot;常青的载体&quot;">​</a></h2><p>大多数人赚不到钱，是因为他们不懂商业是如何运转的。</p><p>你需要一个好产品（在制作过程中涉及到大量技能），你还需要想要这个产品的人。</p><p>让我们来预演一个场景：</p><p>我想卖一本手帐（计划本）。</p><p>所以，我先在自己身上做实验。</p><p>为什么？因为你需要经验和结果。大多数企业失败，是因为他们试图把东西卖给那些遇到问题的人，而他们自己却从未经历过这个问题。</p><p>我在亚马逊上买了4-5本最畅销的手帐。</p><p>我买了一些关于生产力的书和课程。</p><p>我沉浸在关于生产力技巧的播客、社交媒体账号和视频中。</p><p>我规划我的日程，安排我的工作，并学以致用。</p><p>到这个时候，我就知道该如何改进我想卖的这本手帐了——或者根据我在研究中发现的东西，做一个全新的产品。</p><p>我也完全接触到了让这项业务运转的整个过程。</p><ul><li>我听过表现优异的社交媒体内容（我可以重新创作它们来推广我的手帐，并在不打广告的情况下建立粉丝群）。</li><li>我已经从那些以此谋生的人那里购买了手帐、书籍和课程（所以我可以对他们的营销和网页进行逆向工程）。</li><li>我已经获得了结果，所以我对这个问题、渴望的结果以及实现该结果的系统有了直接的经验（这就构成了我的营销策略）。</li></ul><p>这一切都在你眼前，但你却没有注意。</p><p>如果你想在工作之外赚钱，你需要<strong>分发渠道和一个产品</strong>。</p><p>如果你想不受物理位置限制，以一个人的身份来做这件事，你需要<strong>代码和内容</strong>。</p><p>代码是互联网的后端。</p><p>内容是互联网的前端。</p><p>代码是你托管内容的方式。</p><p>内容是你获取注意力的方式。</p><p>你不需要学习如何写代码，因为技术已经进步到了我们现在的程度。</p><p>以前需要10个员工才能建立的会员网站，现在只要1个人购买软件就能搞定。</p><p>你可以点击“发布”，让一个大V账号看到那篇帖子并分享它，然后在你之前从未发过帖的情况下获得几十万的浏览量。</p><p>你可以建立一个读者群，让你能在生活中随心所欲。你不再被束缚在某一个固定的细分领域中。</p><p>总而言之，我想说的是，内容创作不再是可选项了。</p><p>几年前它还是个可选项，但市场在进化。</p><blockquote><p>销售周期越来越长。\\</p><p>潜在客户对你的考察也越来越多。\\</p><p>谁拥有最多和最好的内容，谁就能赢。</p><p>— 邮件开发营销奇才 📩 (@blackhatwizardd) <a href="https://twitter.com/blackhatwizardd/status/1686149523704332288?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2023年7月31日</a></p></blockquote><p>内容就是你分发产品的方式。</p><p>营销和销售是你创造真正被市场所重视的产品和内容的方式。</p><p>无论你还学了什么其他东西，这些都是你需要优先掌握的核心技能。</p><p>营销、销售、写作和表达，而内容就是承载所有这一切的载体。</p><p>如果“内容”对你来说有些不知所云，那就买几门社交媒体课程。或者去看看<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer（两小时写手）。</a></p><h2 id="现代职业道路" tabindex="-1">现代职业道路 <a class="header-anchor" href="#现代职业道路" aria-label="Permalink to &quot;现代职业道路&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>即使大多数人不看好创作者经济，我也对其充满信心。</p><p>我把它看作是大自然纠正工业革命所犯错误的一种方式。</p><p>学校教育正在被内容和课程去中心化。</p><p>学生可以追随他们的好奇心，并快速适应时代。</p><p>对于那些自我教育并获取技能，去为其他创作者工作，并最终为自己工作的人来说，8小时工作制和薪资奴役将走向终结。</p><p>以下是我预测的现在和未来的职业道路：</p><h3 id="_1-代码与内容" tabindex="-1">1) 代码与内容 <a class="header-anchor" href="#_1-代码与内容" aria-label="Permalink to &quot;1) 代码与内容&quot;">​</a></h3><blockquote><p>代码和媒体是无需许可的杠杆。它们是新晋富豪背后的杠杆。你可以创造出在你睡觉时也能为你工作的软件和媒体。—— Naval（纳瓦尔）</p></blockquote><p>大多数人将不得不从代码或内容开始起步。</p><p>所以，你要么成为一名程序员，要么成为一名内容营销人员。</p><p>你可以两者都学，但这当然需要时间。（这是最强大的技能栈之一）。</p><p>程序员可以为创作者、初创企业乃至几乎任何现代工作服务。他们可以做自由职业者，也可以被上述所有人雇佣。</p><p>内容营销人员也完全一样。每个人（企业）都有内容、营销、销售或任何形式的媒体团队。</p><p>大多数人都应该通过写内容来打造自己的公开简历（或个人品牌）。</p><p>那将是你未来找到客户、工作和吸引顾客的地方。</p><p>你的个人品牌就是你在线上的“角色”。</p><p>如果你选择不学写代码，这也完全没问题，因为现代软件已经让你没有这个必要了。</p><h3 id="_2-营销与销售" tabindex="-1">2) 营销与销售 <a class="header-anchor" href="#_2-营销与销售" aria-label="Permalink to &quot;2) 营销与销售&quot;">​</a></h3><blockquote><p>学会销售，学会构建（打造产品），如果你两样都能做，你将势不可挡。—— Naval</p></blockquote><p>这两条路径最终都会交汇在学习营销和销售的<strong>必然性</strong>上。</p><p>大多数软件公司和程序员失败的原因是，他们能打造出一个产品，但却卖不出去。</p><p>创作者也是如此。</p><p>他们可以通过优秀的写作来积累受众，但到了要创造出一个人们真正想要的产品时，他们就力不从心了。</p><p>如果你想在一份不可避免会失去光泽并把你禁锢在薪水上的工作之外生存下来，营销和销售就是你在创业狩猎中的武器。</p><h3 id="_3-建立分发渠道" tabindex="-1">3) 建立分发渠道 <a class="header-anchor" href="#_3-建立分发渠道" aria-label="Permalink to &quot;3) 建立分发渠道&quot;">​</a></h3><blockquote><p>建立分发渠道，然后再做任何你想做的事。—— 杰克·布彻 (Jack Butcher)</p></blockquote><p>在数字化致富竞赛中，分发渠道是你能理解的最重要的概念。</p><p>分发方法的杠杆作用各不相同。</p><p>自由职业者、代理机构、本地企业甚至初创公司，通常专注于低杠杆、能带来即时满足感的分发方法：</p><ul><li>冷邮件</li><li>付费广告</li><li>直接私信</li></ul><p>当然，这些仍然是获取客户的可行方法，但如果你停止在上面投入精力，你往往会一无所有。</p><p>你最好建立长期的分发渠道（同时混合使用其他方法以快速获利）：</p><ul><li><strong>建立受众</strong> —— 比如在 X 上建立 10 万粉丝的受众。</li><li><strong>向你的网络推广</strong> —— 比如让你拥有 10 万粉丝的网友推广你的作品。</li><li><strong>租用他人的受众</strong> —— 比如赞助时事通讯（newsletter）或 YouTube 频道，从而在数百万感兴趣的人面前曝光。</li></ul><p>你必须把社交媒体作为一种技能来学习，以接入全球分发渠道。</p><p>在你撰写内容和建立受众的同时，你仍然可以发邮件、发私信或投放付费广告，从而立即开始赚钱。</p><p>给你个直观的概念，仅在 X 上，我每个月就能获得大约 1200 万次曝光（impressions）。算上其他平台，这个数字可能要翻两番。</p><p>通过谷歌搜索（我不知道这有多准确），付费广告的低 CPM（千次曝光成本）大约是 3 美元（1000 次曝光）。</p><p>每个月仅在 X（前 Twitter）上，我获得的曝光量相当于我每个月要花 36,000 美元才能买到的。</p><p>如果你的内容或广告是有利可图的——你应该能从中每个月赚到远超 100,000 美元的收入。</p><h3 id="_4-从可雇佣到不可雇佣" tabindex="-1">4) 从可雇佣到不可雇佣 <a class="header-anchor" href="#_4-从可雇佣到不可雇佣" aria-label="Permalink to &quot;4) 从可雇佣到不可雇佣&quot;">​</a></h3><p>到了某个阶段，你会清楚自己再也不会受雇于人了。</p><p>你的技能复利积累，让你懂得如何在任何市场条件下赚钱。</p><p>我会遵循的进阶过程是这样的：</p><ul><li>开始学习所有品牌都需要的技能——营销、销售、品牌建设、内容、设计等。</li><li>申请工作或为某位创作者工作，以获取真实世界的经验（并赚点钱）。这可以是自由职业，也可以是全职雇佣。</li><li>每天至少花 1 小时建立你自己的事业。撰写内容，不断迭代直到获得增长，并推广你的报价（offer）。</li><li>随着受众的增长，开始过渡到做你自己的事情。扩展你的产品栈，去触达你受众中的更多人。</li></ul><p>通过这种方式，你的未来几乎不可能得不到保障。</p><p>如果你的营销技能不过关，庞大的受众可以弥补这一点。</p><p>如果你建立受众的技能不过关，营销和销售知识可以弥补这一点。</p><p>多元化的技能栈，再加上每天的努力，将解决你的大部分问题。</p><h3 id="_5-迭代式产品" tabindex="-1">5) 迭代式产品 <a class="header-anchor" href="#_5-迭代式产品" aria-label="Permalink to &quot;5) 迭代式产品&quot;">​</a></h3><p>大多数创作者失败的原因，是因为他们把变现视为一锤子买卖。</p><p>你的产品和服务会随着你的成长而<em>进化</em>。它们相互依存、层层递进。如果你从不发布第一款产品，你就无法打造出更好的产品。</p><p>停滞 = 死亡。</p><p>我的网页设计服务进化成了销售漏斗。我的漏斗知识进化成了 3 款数字产品。这些数字产品进化成了一个社群。我一路走来的经验又创造了 2 款数字产品。我的 10 多个引流品（lead magnets）进化成了一本计划册，现在它正和我的书一起在 9 月下旬重新发布。以上所有的东西都在进化成我正在构建的软件。永无止境。这正是让它充满意义的原因。</p><p>显而易见，如果某个东西卖不出去，那是你的问题，而不是市场的问题。</p><p>如果你不断学习并完善你的技能栈，你就会在你的产品中看到改进的机会。</p><p>所有这些商业上的事，不过是终生的坚持和迭代。</p><p>继续打造吧。</p><p>—— 丹·柯 (Dan Koe)</p><hr><p><a href="/en/letters/i-had-to-learn-these-high-income-skills-if-i-wanted-to-make-money">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',150))])}const w=r(c,[["render",d]]);export{q as __pageData,w as default};
